// ── Node 2: Verify HMAC + validate inbound payload (rev7 — partial-batch) ───
// Accepts either:
//   { brand_id, fields: [{field_name, current_value, corrected_value, reasoning}] }  (batch)
//   { brand_id, field_name, current_value, corrected_value, reasoning }               (legacy single)
// Per-field validation: invalid fields are SKIPPED with a reason logged — valid
// fields continue. Only hard-reject when ZERO valid fields remain.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';

const headers = $input.first().json.headers || {};
const given   = headers['x-n8n-signature'];
const ts      = headers['x-n8n-timestamp'];
const rid     = headers['x-n8n-request-id'];

if (!given || !ts || !rid) {
  return { json: { _rejected: true, _rejection_reason: 'Missing required HMAC headers', brand_id: null, fields: [] } };
}

const drift = Math.abs(Date.now() - new Date(ts).getTime());
if (drift > 24 * 60 * 60 * 1000) {
  return { json: { _rejected: true, _rejection_reason: `Timestamp drift too large (${drift}ms)`, brand_id: null, fields: [] } };
}

const rawBody  = JSON.stringify($input.first().json.body);
const expected = crypto.createHmac('sha256', SECRET).update(rawBody).digest('hex');
if (expected !== given) {
  return { json: { _rejected: true, _rejection_reason: 'HMAC signature mismatch', brand_id: null, fields: [] } };
}

const body = $input.first().json.body || {};

if (!body.brand_id) {
  return { json: { _rejected: true, _rejection_reason: 'brand_id is required', brand_id: null, fields: [] } };
}

// Complete allowlist — kept in sync with apps/web/src/app/actions/brand-correction.ts
const ALLOWED_FIELDS = new Set([
  'arabic_dialect','price_position','formality_level','humor_tolerance',
  'religious_sensitivity','bilingual_ratio','brand_differentiator',
  'primary_kpi_type','primary_channel','ramadan_relevance',
  'tone_anti_attribute_ids','archetype_primary','archetype_secondary',
  'lifecycle_stage','intent_state','primary_color_hex',
  'audience_description_ar','audience_age_range','audience_language_preference',
  'sub_sector','region_primary','tone_register','archetype_family',
  'founding_story','owner_values','comfort_on_camera','way_of_speaking',
  'communication_style','brand_goals','posting_rhythm','caption_style',
  'permission_level','cultural_tension_owned','goal_phase','brave_safe_default',
  'national_day_relevance','eid_fitr_relevance','eid_adha_relevance','founding_day_relevance',
  'emotions','occasions_ranked','lifestyle','music','music_link','brand_refs',
  'price_nums','vision','vision_text','tagline','cust_quote','caption_ex',
  'metric','anything','custom_restriction','custom_occasion',
  'scale_minmax','scale_quietloud','scale_localglobal','scale_tradmod',
  'social','platforms','name_meaning','hero_why','lifecycle',
  'respected_brands','respected_why','goal','problems',
  'founded_year','brand_name_en','city_primary','sector',
  // AudienceProfile namespaced variants
  'AudienceProfile.description_ar','AudienceProfile.age_range','AudienceProfile.language_preference',
]);

// Normalise to a fields array regardless of input shape
let rawFields;
if (Array.isArray(body.fields) && body.fields.length > 0) {
  rawFields = body.fields;
} else if (body.field_name) {
  rawFields = [{ field_name: body.field_name, current_value: body.current_value ?? null, corrected_value: body.corrected_value, reasoning: body.reasoning ?? null }];
} else {
  return { json: { _rejected: true, _rejection_reason: 'Either fields[] or field_name is required', brand_id: body.brand_id, fields: [] } };
}

// Validate each field — skip invalid ones, continue with valid ones
const validatedFields = [];
const skippedFields = [];
for (const f of rawFields) {
  if (!f.field_name) { skippedFields.push({ field_name: '?', reason: 'missing field_name' }); continue; }
  if (!ALLOWED_FIELDS.has(f.field_name)) { skippedFields.push({ field_name: f.field_name, reason: 'not a correctable BrandDNA field' }); continue; }
  if (!f.corrected_value && f.corrected_value !== 0) { skippedFields.push({ field_name: f.field_name, reason: 'corrected_value is required' }); continue; }
  const correctedNorm = String(f.corrected_value ?? '').trim();
  validatedFields.push({
    field_name:      f.field_name,
    current_value:   f.current_value  || null,
    corrected_value: correctedNorm,
    reasoning:       f.reasoning      || null,
  });
}

// Hard-reject only if nothing valid remains
if (validatedFields.length === 0) {
  const reason = skippedFields.length > 0
    ? skippedFields.map(s => `${s.field_name}: ${s.reason}`).join('; ')
    : 'No valid fields to process';
  return { json: { _rejected: true, _rejection_reason: reason, brand_id: body.brand_id, fields: [], skipped_fields: skippedFields } };
}

const fieldNames = validatedFields.map(f => f.field_name);

return { json: {
  _rejected:      false,
  brand_id:       body.brand_id,
  slug:           body.slug || null,
  fields:         validatedFields,
  field_names:    fieldNames,
  skipped_fields: skippedFields,
  request_id:     rid,
  received_at:    new Date().toISOString(),
}};

// Validation-error path: emit correction_rejected stage so the UI
// immediately shows the error instead of staying stuck on 'Queued'.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d      = $json;
const reason = d._rejection_reason || 'Validation failed';

let stageBody = null;
let stageHeaders = null;
if (d.brand_id) {
  const sb = JSON.stringify({ brand_id: d.brand_id, stage: 'correction_rejected', fields: d.fields || [], metadata: { rejection_reason: reason } });
  const sts = new Date().toISOString();
  const ssig = crypto.createHmac('sha256', SECRET).update(sb).digest('hex');
  stageBody = sb;
  stageHeaders = { 'content-type': 'application/json', 'x-n8n-signature': ssig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': sts };
}

return { json: { ...d, _reason: reason, _stage_body: stageBody, _stage_headers: stageHeaders } };

// Emit stage: correction_received — UI shows 'Received' for ALL fields
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d = $json;
const body = JSON.stringify({ brand_id: d.brand_id, stage: 'correction_received', fields: d.field_names });
const ts = new Date().toISOString();
const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return { json: { ...d,
  _stage_body: body,
  _stage_headers: { 'content-type': 'application/json', 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': ts },
}};

// Build CEO classify body + emit stage: ceo_classifying
// CEO gets ALL fields in trigger_payload so it can nominate memory writes for each.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d = $('Verify HMAC + parse').first().json;
const stageBody = JSON.stringify({ brand_id: d.brand_id, stage: 'ceo_classifying', fields: d.field_names });
const stageTs  = new Date().toISOString();
const stageSig = crypto.createHmac('sha256', SECRET).update(stageBody).digest('hex');
const evidenceBundleStates = {
  arabic_dialect:        'inferred_medium',
  price_position:        'inferred_medium',
  formality_level:       'inferred_medium',
  humor_tolerance:       'inferred_medium',
  religious_sensitivity: 'inferred_medium',
  bilingual_ratio:       'inferred_medium',
  brand_differentiator:  'inferred_medium',
  primary_kpi_type:      'inferred_medium',
  primary_channel:       'inferred_medium',
  ramadan_relevance:     'inferred_medium',
  archetype_primary:     'inferred_medium',
  lifecycle_stage:       'inferred_medium',
};
// Pass the full fields array so CEO can produce nominations for each
const ceoBody = JSON.stringify({
  flow_id:  'N8N-A04',
  brand_id: d.brand_id,
  payload:  {
    request_type: 'brand_correction',
    trigger_payload: {
      fields:        d.fields,
      submitted_via: 'correction_form_batch',
    },
    evidence_bundle_states:  evidenceBundleStates,
    occasion_flags:          ['none'],
    current_month_spend_usd: 0,
    monthly_ceiling_usd:     50,
  },
});
const ceoTs  = new Date().toISOString();
const ceoSig = crypto.createHmac('sha256', SECRET).update(ceoBody).digest('hex');
return { json: { ...d,
  _stage_body: stageBody,
  _stage_headers: { 'content-type': 'application/json', 'x-n8n-signature': stageSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': stageTs },
  _ceo_raw_body: ceoBody,
  _ceo_headers: { 'content-type': 'application/json', 'x-n8n-signature': ceoSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': ceoTs },
}};

// Parse CEO response + decide approved/rejected
const raw      = $('POST · /api/agents/ceo/classify').first().json;
const inbound  = $('Verify HMAC + parse').first().json;

const ok       = raw?.ok === true;
const decision = raw?.result?.decision ?? {};
const memory   = raw?.result?.memory   ?? {};

const nominated = (memory.enqueued ?? 0) + (memory.skipped_duplicates ?? 0);
const hasWork   = nominated > 0;
const approved  = ok && hasWork;

const rejectionReason = !ok
  ? (raw?.error ?? 'CEO classify call failed')
  : !hasWork
    ? 'CEO did not produce any nominations for this correction'
    : null;

return { json: {
  ...inbound,
  _ceo_resp:         raw,
  _decision:         decision,
  _approved:         approved,
  _enqueued:         memory.enqueued           ?? 0,
  _duplicates:       memory.skipped_duplicates ?? 0,
  _dropped:          memory.dropped            ?? 0,
  _routing_id:       decision.decision_id      ?? null,
  _rejection_reason: rejectionReason,
}};

// Approved path: emit stage ceo_approved + build memory body
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d = $('Verify HMAC + parse').first().json;
const stageBody = JSON.stringify({ brand_id: d.brand_id, stage: 'ceo_approved', fields: d.field_names });
const stageTs  = new Date().toISOString();
const stageSig = crypto.createHmac('sha256', SECRET).update(stageBody).digest('hex');
const memBody  = JSON.stringify({ flow_id: 'N8N-A04', batch_size: 50 });
const memTs    = new Date().toISOString();
const memSig   = crypto.createHmac('sha256', SECRET).update(memBody).digest('hex');
return { json: { ...d,
  _ceo_resp:   $('Parse CEO response').first().json._ceo_resp,
  _routing_id: $('Parse CEO response').first().json._routing_id,
  _stage_body: stageBody,
  _stage_headers: { 'content-type': 'application/json', 'x-n8n-signature': stageSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': stageTs },
  _mem_raw_body: memBody,
  _mem_headers: { 'content-type': 'application/json', 'x-n8n-signature': memSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': memTs },
}};

// Qdrant invalidate + emit stage memory_writing
const crypto   = require('crypto');
const SECRET   = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d        = $('Verify HMAC + parse').first().json;
const qBody    = JSON.stringify({ brand_id: d.brand_id, flow_id: 'N8N-A04' });
const qTs      = new Date().toISOString();
const qSig     = crypto.createHmac('sha256', SECRET).update(qBody).digest('hex');
const stageBody = JSON.stringify({ brand_id: d.brand_id, stage: 'memory_writing', fields: d.field_names });
const stageTs  = new Date().toISOString();
const stageSig = crypto.createHmac('sha256', SECRET).update(stageBody).digest('hex');
return { json: {
  brand_id: d.brand_id,
  fields:   d.fields,
  field_names: d.field_names,
  _mem_result: $('POST · /api/memory/process').first().json?.result || {},
  _qdrant_raw_body: qBody,
  _qdrant_headers: { 'content-type': 'application/json', 'x-n8n-signature': qSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': qTs },
  _stage_body: stageBody,
  _stage_headers: { 'content-type': 'application/json', 'x-n8n-signature': stageSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': stageTs },
}};

// Build correction_applied callback — includes all field names in payload
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d      = $('Verify HMAC + parse').first().json;
const memR   = $('POST · /api/memory/process').first().json?.result || {};
const cbBody = JSON.stringify({
  event_type: 'correction_applied',
  flow_id:    'N8N-A04',
  brand_id:   d.brand_id,
  payload: {
    fields:          d.field_names,
    memory_written:  memR.written  ?? 0,
    memory_rejected: memR.rejected ?? 0,
    memory_skipped:  memR.skipped  ?? 0,
  },
});
const ts  = new Date().toISOString();
const sig = crypto.createHmac('sha256', SECRET).update(cbBody).digest('hex');
return { json: { ...d,
  _cb_raw_body: cbBody,
  _cb_headers: { 'content-type': 'application/json', 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': ts },
}};

// Rejected path: build rejection callback + ceo_rejected stage emit
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const d    = $('Verify HMAC + parse').first().json;
const ceoR = $('Parse CEO response').first().json;
const reason = ceoR._rejection_reason || 'CEO did not approve this correction';
const cbBody = JSON.stringify({
  event_type: 'correction_rejected',
  flow_id:    'N8N-A04',
  brand_id:   d.brand_id,
  payload: {
    fields:           d.field_names,
    rejection_reason: reason,
    human_gate:       ceoR._decision?.human_gate_required ?? false,
    anomaly_flag:     ceoR._decision?.anomaly_flag ?? null,
  },
});
const cbTs  = new Date().toISOString();
const cbSig = crypto.createHmac('sha256', SECRET).update(cbBody).digest('hex');
const stageBody = JSON.stringify({ brand_id: d.brand_id, stage: 'correction_rejected', fields: d.field_names, metadata: { rejection_reason: reason } });
const stageTs  = new Date().toISOString();
const stageSig = crypto.createHmac('sha256', SECRET).update(stageBody).digest('hex');
return { json: { ...d,
  _rej_reason:  reason,
  _stage_body:  stageBody,
  _stage_headers: { 'content-type': 'application/json', 'x-n8n-signature': stageSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': stageTs },
  _cb_raw_body: cbBody,
  _cb_headers: { 'content-type': 'application/json', 'x-n8n-signature': cbSig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': cbTs },
}};

// Build HMAC-signed S03 alert — fires on any unhandled A04 error.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const e = $json;

let brand_id = null;
try { brand_id = $('Verify HMAC + parse').first().json.brand_id ?? null; } catch (_) {}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'n8n_failure',
  severity:     'error',
  source_flow:  'N8N-A04',
  brand_id,
  message:      e.execution?.error?.message || 'A04 brand-correction flow failed',
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-a04`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
};
